import {journeyAt,journeyChapters} from './demo-journey-model.mjs';
import {crew,findings,COURSE} from './core.mjs';
const app=document.querySelector('#demo-app');
const requestedStep=Number(new URLSearchParams(location.search).get('step'));
let step=Number.isInteger(requestedStep)&&requestedStep>=0&&requestedStep<8?requestedStep:0;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages=['Purchase','Missing access','Investigation','Preview','Approval','Grant','Verification','Confirmation'];
function render(){
 const {state:s,chapter,verified,confirmed}=journeyAt(step);
 const main=step===0?'Maya chooses The Light & Story Workshop. The checkout has not happened yet.':step===1?'The sample payment is marked complete, but Maya cannot open her workshop. This is the problem the merchant sees.':step===2?'Ledger, Relay, Patch, and Prism compare the purchase and access records. Their findings are scripted sample data here.':step===3?'A copy of the entitlement shows the smallest proposed change. Maya’s payment and account are unchanged.':step===4?'The merchant approves that exact sample preview. Approval does not apply the change by itself.':step===5?'One sample entitlement change is recorded. The case remains open until payment, access, and lesson checks agree.':step===6?'The simulated checks now agree. Maya can try the lesson, but her own confirmation is still separate.':'Maya confirms she can open her purchase. The sample journey ends with both technical proof and customer confirmation.';
 app.innerHTML=`<div class="demo-progress"><span>STEP ${step+1} OF 8 · ${esc(chapter.actor)}</span><div class="demo-meter"><i style="width:${(step+1)/8*100}%"></i></div></div><div class="demo-layout"><section class="demo-stage"><span class="eyebrow">${esc(stages[step])}</span><h2>${esc(chapter.title)}</h2><p>${esc(main)}</p><div class="demo-purchase"><img src="assets/paypal-mark.svg" alt="" width="30" height="30"><div><strong>${esc(COURSE.name)}</strong><small>Maya · $128.00 USD · SAMPLE PURCHASE</small></div><span class="demo-state ${s.capture?'on':''}">${s.capture?'Payment recorded':'Checkout pending'}</span></div><div class="demo-evidence"><div><strong>${s.capture?'6/6':'0/6'}</strong><span>purchase checks ${s.capture?'shown':'awaiting payment'}</span></div><div><strong>${s.writes}</strong><span>sample access grants</span></div><div><strong>${verified?'Passed':'Pending'}</strong><span>lesson proof</span></div><div><strong>${confirmed?'Yes':'No'}</strong><span>customer confirmation</span></div></div>${step>=2?`<details class="demo-agent"><summary>What did the four specialists say?</summary>${findings(s).map((finding,i)=>`<article><strong>${esc(crew[i].name)} · ${esc(crew[i].role)}</strong><p>${esc(finding.summary)}</p><small>Limitation: ${esc(finding.unknown)}</small></article>`).join('')}</details>`:''}${step>=3?`<div class="demo-preview"><span>BEFORE: Course locked</span><b>→</b><span>AFTER: Purchased course active</span></div>`:''}<div class="demo-actions"><button id="previous" ${step===0?'disabled':''}>← Back</button><button id="next" class="primary">${esc(chapter.next)} →</button></div></section><aside class="demo-side"><h3>What Maya sees</h3><div class="demo-message"><span class="demo-avatar">M</span><p>${step<1?'I’m ready to purchase the workshop.':step<5?'I paid, but I still can’t open my course. Can someone tell me what’s happening?':step<6?'I see an update, but I’m waiting for confirmation that the lesson opens.':step<7?'The lesson opens now. I’m going to try it on my device.':'I can access my purchase. Thank you!'}</p></div><h3>What the merchant controls</h3><ul><li>${step>=4?'✓':'○'} Exact preview approval</li><li>${step>=5?'✓':'○'} One access grant</li><li>${verified?'✓':'○'} Independent verification</li><li>${confirmed?'✓':'○'} Customer confirmation</li></ul><p class="demo-boundary">This walkthrough uses fictional records and scripted specialists. It does not call PayPal, grant real access, or send a customer message.</p></aside></div><div class="demo-step-list">${stages.map((name,i)=>`<button data-step="${i}" class="${i===step?'current':''}" aria-label="Show step ${i+1}: ${esc(name)}" aria-current="${i===step?'step':'false'}"><span>${i<step?'✓':i+1}</span>${esc(name)}</button>`).join('')}</div>`;
 app.querySelector('#previous').onclick=()=>{step--;render();};app.querySelector('#next').onclick=()=>{step=step===7?0:step+1;render();};app.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>{step=Number(button.dataset.step);render();});
}
render();
